const formatTime = (seconds, includeHours = true) => {
  const safeSeconds = Math.max(0, Math.floor(seconds));
  const hours = Math.floor(safeSeconds / 3600).toString().padStart(2, '0');
  const minutes = Math.floor((safeSeconds % 3600) / 60).toString().padStart(2, '0');
  const remainder = (safeSeconds % 60).toString().padStart(2, '0');
  return includeHours ? `${hours}:${minutes}:${remainder}` : `${hours}:${minutes}`;
};
function loadState() { try { return { ...defaultState, ...JSON.parse(localStorage.getItem(STORAGE_KEY)) }; } catch { return structuredClone(defaultState); } }
function saveState() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); return true; } catch (error) { return false; } }
function sessionSecondsFor(contractId, filterFn) { const sessions = state.editSessions[contractId] || []; return sessions.filter(filterFn).reduce((sum, session) => sum + Math.max(0, (timeToMinutes(session.end) - timeToMinutes(session.start)) * 60), 0); }
