function lifetimeSessionSeconds(contractId) { return sessionSecondsFor(contractId, () => true); }
function contractSeconds(contract) { return lifetimeSessionSeconds(contract.id) + (contract.startedAt ? Math.floor((Date.now() - contract.startedAt) / 1000) : 0); }
function isDateCommitted(date) { return state.committedDates.includes(date); }
function recordSession(contract, startMs, endMs) { const safeEndMs = Math.max(endMs, startMs + 1000); const date = localDateString(startMs); const start = timeOfDaySecondsString(startMs); const end = timeOfDaySecondsString(safeEndMs); const sessions = state.editSessions[contract.id] || (state.editSessions[contract.id] = []); sessions.push({ id: `session-${contract.id}-${Date.now()}`, date, start, end }); }
function nonWorkingSeconds(entry) { const [startHour, startMinute] = entry.start.split(':').map(Number); const [endHour, endMinute] = entry.end.split(':').map(Number); return Math.max(0, (endHour * 60 + endMinute - startHour * 60 - startMinute) * 60); }
function timeToMinutes(value) { const [hours, minutes, seconds] = value.split(':').map(Number); return hours * 60 + minutes + (seconds || 0) / 60; }
function minutesToTime(minutes) { const rounded = Math.round(minutes); return `${Math.floor(rounded / 60).toString().padStart(2, '0')}:${(rounded % 60).toString().padStart(2, '0')}`; }
function scheduleBreakSeconds(breakItem) { return Math.max(0, (timeToMinutes(breakItem.end) - timeToMinutes(breakItem.start)) * 60); }
function currentBreak() { const entry = state.workingTimes.find((item) => item.userId === 'jordan'); if (!entry) return null; const now = new Date(); const minutes = now.getHours() * 60 + now.getMinutes(); return entry.breaks.find((breakItem) => minutes >= timeToMinutes(breakItem.start) && minutes < timeToMinutes(breakItem.end)); }
function sessionsForDate(date) { const list = []; state.contracts.forEach((contract) => { (state.editSessions[contract.id] || []).forEach((session) => { if (session.date === date) list.push({ contractId: contract.id, session }); }); }); list.sort((a, b) => timeToMinutes(a.session.start) - timeToMinutes(b.session.start)); return list; }
