function enforceMinimumDuration(session, prevSession, nextSession, handleType) { const MIN = 5; if (handleType === 'start') { if (timeToMinutes(session.end) - timeToMinutes(session.start) <= 0) session.start = minutesToTime(timeToMinutes(session.end) - MIN); if (prevSession && timeToMinutes(prevSession.end) - timeToMinutes(prevSession.start) <= 0) { prevSession.end = minutesToTime(timeToMinutes(prevSession.start) + MIN); session.start = prevSession.end; } } else { if (timeToMinutes(session.end) - timeToMinutes(session.start) <= 0) session.end = minutesToTime(timeToMinutes(session.start) + MIN); if (nextSession && timeToMinutes(nextSession.end) - timeToMinutes(nextSession.start) <= 0) { nextSession.start = minutesToTime(timeToMinutes(nextSession.end) - MIN); session.end = nextSession.start; } } }
function renderContracts() {
  const filter = $('#filter-contracts').value;
  let contracts = state.order.map((id) => state.contracts.find((contract) => contract.id === id)).filter(Boolean);
  if (filter === 'visible') contracts = contracts.filter((contract) => !contract.hidden);
  if (filter === 'hidden') contracts = contracts.filter((contract) => contract.hidden);
  const emptyMessage = filter === 'hidden' ? 'No hidden contracts.' : 'No contracts on your dashboard yet. Add one to get started.';
  $('#contract-grid').innerHTML = contracts.length ? contracts.map(contractTemplate).join('') : `<div class="empty-dashboard">${emptyMessage}</div>`;
  document.querySelectorAll('.clock-button').forEach((button) => button.addEventListener('click', () => toggleClock(button.dataset.id)));
  document.querySelectorAll('.pin-action').forEach((button) => button.addEventListener('click', () => togglePin(button.dataset.id)));
  document.querySelectorAll('.edit-contract').forEach((button) => button.addEventListener('click', () => openContractModal(button.dataset.id)));
  document.querySelectorAll('.delete-contract').forEach((button) => button.addEventListener('click', () => toggleTileVisibility(button.dataset.id)));
  document.querySelectorAll('.tile').forEach(enableDrag);
  document.querySelectorAll('.tile-image img').forEach((img) => img.addEventListener('click', () => openImageViewer(img.getAttribute('src'))));
  updateMetrics();
}
function contractTemplate(contract) { const running = Boolean(contract.startedAt); return `<article class="tile ${contract.pinned ? 'is-pinned' : ''} ${contract.hidden ? 'is-hidden-contract' : ''}" draggable="${!contract.pinned}" data-id="${contract.id}"><div class="tile-title-bar"><span class="drag-handle" title="Drag to arrange">&#10303;</span><strong class="tile-customer-name" title="${contract.customerName}">${contract.customerName}</strong><button class="tile-action pin-action" data-id="${contract.id}" title="${contract.pinned ? 'Unpin tile' : 'Pin tile'}" aria-label="${contract.pinned ? 'Unpin tile' : 'Pin tile'}">&#128205;</button></div><div class="tile-meta"><span class="tile-code">${contract.number} | ${contract.suffix}${contract.suffixDescription ? ` - ${contract.suffixDescription}` : ''}</span>${contract.machineType ? `<span class="tile-machine-type">${contract.machineType}</span>` : ''}</div><div class="tile-image">${contract.image ? `<img src="${contract.image}" alt="${contract.customerName}">` : 'Image placeholder'}</div><div class="tile-times"><div class="time-block"><span>Accumulated</span><strong>${formatTime(contractSeconds(contract))}</strong></div><div class="time-block"><span>Current session</span><strong class="${running ? 'live-time' : ''}" data-live-id="${contract.id}">${running ? formatTime(Math.floor((Date.now() - contract.startedAt) / 1000)) : '00:00:00'}</strong></div></div><div class="tile-footer"><div class="tile-footer-left"><button class="tile-action edit-contract" data-id="${contract.id}" title="Edit tile" aria-label="Edit tile">&#9998;</button><button class="tile-action delete-contract" data-id="${contract.id}" title="${contract.hidden ? 'Restore tile to dashboard' : 'Remove tile from dashboard'}" aria-label="${contract.hidden ? 'Restore tile to dashboard' : 'Remove tile from dashboard'}">${contract.hidden ? '&#8635;' : '&times;'}</button></div><button class="clock-button ${running ? 'is-running' : ''}" data-id="${contract.id}" type="button">${running ? 'Stop clock' : 'Start clock'}</button></div></article>`; }
const imageViewerState = { scale: 1, fitScale: 1, x: 0, y: 0, naturalWidth: 0, naturalHeight: 0 };
function openImageViewer(src) { const img = $('#image-viewer-img'); const onReady = () => { imageViewerState.naturalWidth = img.naturalWidth; imageViewerState.naturalHeight = img.naturalHeight; zoomToFit(); }; img.onload = onReady; img.src = src; if (img.complete && img.naturalWidth) onReady(); $('#image-viewer-modal').classList.remove('is-hidden'); }
function closeImageViewer() { $('#image-viewer-modal').classList.add('is-hidden'); }
function applyImageTransform() { $('#image-viewer-img').style.transform = `translate(${imageViewerState.x}px, ${imageViewerState.y}px) scale(${imageViewerState.scale})`; }
function zoomToFit() { const viewport = $('#image-viewer-viewport'); const rect = viewport.getBoundingClientRect(); const fit = Math.min(rect.width / imageViewerState.naturalWidth, rect.height / imageViewerState.naturalHeight, 1) || 1; imageViewerState.fitScale = fit; imageViewerState.scale = fit; imageViewerState.x = 0; imageViewerState.y = 0; applyImageTransform(); }
function zoomBy(factor) { imageViewerState.scale = Math.min(4, Math.max(imageViewerState.fitScale, imageViewerState.scale * factor)); applyImageTransform(); }
function enableImagePan(img) { let panning = false; let startX; let startY; let originX; let originY; img.addEventListener('pointerdown', (event) => { panning = true; startX = event.clientX; startY = event.clientY; originX = imageViewerState.x; originY = imageViewerState.y; img.setPointerCapture(event.pointerId); }); img.addEventListener('pointermove', (event) => { if (!panning) return; imageViewerState.x = originX + (event.clientX - startX); imageViewerState.y = originY + (event.clientY - startY); applyImageTransform(); }); img.addEventListener('pointerup', (event) => { panning = false; img.releasePointerCapture(event.pointerId); }); }
function toggleClock(id) { const contract = state.contracts.find((item) => item.id === id); if (!contract) return; if (isDateCommitted(TODAY) && !state.adminMode) { showToast("Today's times are committed — enable admin mode to make changes"); return; } if (contract.startedAt) { recordSession(contract, contract.startedAt, Date.now()); contract.startedAt = null; showToast(`${contract.customerName} stopped and saved`); } else { const runningContract = state.contracts.find((item) => item.id !== id && item.startedAt); if (runningContract) { recordSession(runningContract, runningContract.startedAt, Date.now()); runningContract.startedAt = null; } contract.startedAt = Date.now(); showToast(runningContract ? `${runningContract.customerName} stopped; ${contract.customerName} is now running` : `${contract.customerName} is now running`); } saveState(); renderContracts(); renderEditTimes(); }
function togglePin(id) { const contract = state.contracts.find((item) => item.id === id); contract.pinned = !contract.pinned; saveState(); renderContracts(); showToast(contract.pinned ? 'Tile pinned in place' : 'Tile can be rearranged'); }
function toggleTileVisibility(id) { const contract = state.contracts.find((item) => item.id === id); if (!contract) return; contract.hidden = !contract.hidden; saveState(); renderContracts(); showToast(contract.hidden ? 'Tile removed from dashboard' : 'Tile restored to dashboard'); }
function updateMetrics() { const total = state.contracts.reduce((sum, contract) => sum + todaySessionSeconds(contract.id) + (contract.startedAt ? Math.floor((Date.now() - contract.startedAt) / 1000) : 0), 0); const active = state.contracts.filter((contract) => contract.startedAt).length; const nonWorking = state.workingTimes.reduce((sum, entry) => sum + entry.breaks.reduce((breakTotal, breakItem) => breakTotal + scheduleBreakSeconds(breakItem), 0), 0); const activeCount = $('#active-count'); $('#tracked-total').textContent = formatTime(total); if (activeCount) activeCount.textContent = active; $('#non-working-total').textContent = formatTime(nonWorking, false); }
function enableDrag(tile) { tile.addEventListener('dragstart', () => tile.classList.add('is-dragging')); tile.addEventListener('dragend', () => { tile.classList.remove('is-dragging'); const ids = [...document.querySelectorAll('.tile')].map((item) => item.dataset.id); state.order = ids.concat(state.order.filter((id) => !ids.includes(id))); saveState(); }); tile.addEventListener('dragover', (event) => { event.preventDefault(); if (tile.classList.contains('is-pinned')) return; const dragging = document.querySelector('.is-dragging'); if (dragging && dragging !== tile) { const box = tile.getBoundingClientRect(); tile.parentNode.insertBefore(dragging, event.clientY < box.top + box.height / 2 ? tile : tile.nextSibling); } }); }
function renderWorkingTimes() { const heading = $('#timeline-heading'); heading.innerHTML = Array.from({ length: 24 }, (_, hour) => `<span>${hour.toString().padStart(2, '0')}:00</span>`).join(''); const rows = $('#working-time-rows'); $('#empty-state').classList.toggle('is-hidden', state.workingTimes.length > 0); rows.innerHTML = state.workingTimes.map(workingTimeRowTemplate).join(''); rows.querySelectorAll('[data-entry-field]').forEach((input) => input.addEventListener('change', () => { const entry = state.workingTimes.find((item) => item.id === input.dataset.entryId); entry[input.dataset.entryField] = input.value; saveState(); renderWorkingTimes(); updateMetrics(); })); rows.querySelectorAll('.remove-user').forEach((button) => button.addEventListener('click', () => removeWorkingTimeEntry(button.dataset.entryId))); rows.querySelectorAll('.edit-break').forEach((button) => { button.addEventListener('click', () => { if (button.dataset.longPressed) { delete button.dataset.longPressed; return; } openScheduleModal(button.dataset.entryId); }); enableBreakLongPress(button); }); rows.querySelectorAll('.add-break').forEach((button) => button.addEventListener('click', () => openScheduleModal(button.dataset.entryId))); rows.querySelectorAll('.schedule-handle').forEach(enableScheduleHandle); }
function enableBreakLongPress(breakBlock) { let pressTimer; let longPressed = false; const cancelPress = () => { clearTimeout(pressTimer); }; breakBlock.addEventListener('pointerdown', (event) => { if (event.target.closest('.schedule-handle')) return; longPressed = false; pressTimer = setTimeout(() => { longPressed = true; showConfirm('Delete this break?').then((confirmed) => { if (confirmed) deleteBreak(breakBlock.dataset.entryId, breakBlock.dataset.breakId); else breakBlock.dataset.longPressed = 'true'; }); }, 700); }); breakBlock.addEventListener('pointerup', () => { clearTimeout(pressTimer); if (longPressed) breakBlock.dataset.longPressed = 'true'; }); breakBlock.addEventListener('pointerleave', cancelPress); breakBlock.addEventListener('pointercancel', cancelPress); }
