function openContractModal(contractId = null) { editingContractId = contractId; const contract = contractId ? state.contracts.find((item) => item.id === contractId) : null; $('#contract-modal-title').textContent = contract ? 'Edit tile' : 'Add tile'; $('#contract-submit').innerHTML = contract ? 'Save changes' : '<span>+</span> Add tile'; $('#contract-customer-name').innerHTML = customerOptionsHtml(contract?.customerName || ''); $('#contract-number').innerHTML = contractNumberOptionsHtml(contract?.number || ''); refreshContractSuffixOptions(contract?.suffix || ''); $('#contract-suffix-description').value = contract?.suffixDescription || ''; $('#contract-machine-type').value = contract?.machineType || ''; $('#contract-image').value = ''; $('#contract-image-preview').innerHTML = contract?.image ? `<img src="${contract.image}" alt="Current image"><span>Current image — choose a file to replace it</span>` : ''; $('#contract-modal').classList.remove('is-hidden'); $('#contract-customer-name').focus(); }
function renderScheduleBreakRows() { const container = $('#schedule-break-rows'); container.innerHTML = scheduleBreaksDraft.map((brk, index) => { const isLast = index === scheduleBreaksDraft.length - 1; return `<div class="form-row break-row"><label>Break starts<input type="time" data-break-index="${index}" data-break-field="start" value="${brk.start}"></label><label>Break ends<input type="time" data-break-index="${index}" data-break-field="end" value="${brk.end}"></label><button class="break-row-action ${isLast ? 'add-break-row' : 'remove-break-row'}" data-break-index="${index}" type="button" title="${isLast ? 'Add another break' : 'Remove this break'}" aria-label="${isLast ? 'Add another break' : 'Remove this break'}">${isLast ? '&#43;' : '&times;'}</button></div>`; }).join(''); container.querySelectorAll('[data-break-field]').forEach((input) => input.addEventListener('change', () => { scheduleBreaksDraft[Number(input.dataset.breakIndex)][input.dataset.breakField] = input.value; })); container.querySelectorAll('.add-break-row').forEach((button) => button.addEventListener('click', () => { scheduleBreaksDraft.push({ start: '12:30', end: '13:05' }); renderScheduleBreakRows(); })); container.querySelectorAll('.remove-break-row').forEach((button) => button.addEventListener('click', () => { scheduleBreaksDraft.splice(Number(button.dataset.breakIndex), 1); renderScheduleBreakRows(); })); }
function openScheduleModal(entryId = null) { editingScheduleEntryId = entryId; const entry = state.workingTimes.find((item) => item.id === entryId); const user = entry ? state.users.find((item) => item.id === entry.userId) : null; $('#schedule-modal-title').textContent = user ? `Edit ${user.name}` : 'Add user'; const select = $('#schedule-user-name'); const assignedIds = new Set(state.workingTimes.map((item) => item.userId)); const availableUsers = state.users.filter((item) => item.id === entry?.userId || !assignedIds.has(item.id)); select.innerHTML = '<option value="">Select user</option>' + availableUsers.map((item) => `<option value="${item.id}" ${entry && item.id === entry.userId ? 'selected' : ''}>${item.name}</option>`).join(''); select.disabled = Boolean(entry); $('#schedule-start').value = entry?.start || '06:00'; $('#schedule-end').value = entry?.end || '15:00'; scheduleBreaksDraft = entry && entry.breaks.length ? entry.breaks.map((brk) => ({ id: brk.id, start: brk.start, end: brk.end })) : [{ start: '12:30', end: '13:05' }]; renderScheduleBreakRows(); $('#schedule-modal').classList.remove('is-hidden'); $('#schedule-user-name').focus(); }
