function saveSchedule(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const existingEntry = editingScheduleEntryId ? state.workingTimes.find((item) => item.id === editingScheduleEntryId) : null; const targetUserId = existingEntry ? existingEntry.userId : formData.get('userId'); const start = formData.get('start'); const end = formData.get('end'); if (!targetUserId) { showToast('Select a user'); return; } if (timeToMinutes(end) <= timeToMinutes(start)) { showToast('End time must be after start time'); return; } for (const brk of scheduleBreaksDraft) { if (timeToMinutes(brk.end) <= timeToMinutes(brk.start)) { showToast('Break end times must be after start times'); return; } } const breaks = scheduleBreaksDraft.map((brk, index) => ({ id: brk.id || `break-${Date.now()}-${index}`, type: 'Break', start: brk.start, end: brk.end })); if (existingEntry) { existingEntry.start = start; existingEntry.end = end; existingEntry.breaks = breaks; } else { state.workingTimes.push({ id: `wt-${Date.now()}`, userId: targetUserId, start, end, breaks }); } saveState(); renderWorkingTimes(); updateMetrics(); closeScheduleModal(); showToast(existingEntry ? 'Working times updated' : 'Working times added'); }
function closeContractModal() { $('#contract-modal').classList.add('is-hidden'); $('#contract-form').reset(); $('#contract-image-preview').innerHTML = ''; editingContractId = null; }
function saveContract(event) { event.preventDefault(); const formData = new FormData(event.currentTarget); const customerName = formData.get('customerName').trim(); const number = formData.get('number').trim(); const suffix = formData.get('suffix').trim(); const suffixDescription = formData.get('suffixDescription').trim(); const machineType = formData.get('machineType'); const imageFile = formData.get('image'); const contractId = editingContractId; const finishSaveContract = (image) => { if (contractId) { const contract = state.contracts.find((item) => item.id === contractId); contract.customerName = customerName; contract.number = number; contract.suffix = suffix; contract.suffixDescription = suffixDescription; contract.machineType = machineType; if (image) contract.image = image; } else { const id = `contract-${Date.now()}`; state.contracts.push({ id, customerName, number, suffix, suffixDescription, machineType, image, startedAt: null, pinned: false, hidden: false }); state.order.push(id); state.editSessions[id] = [{ id: `session-${id}-1`, date: EDIT_TIMES_DATE, start: '09:00', end: '09:30' }]; } const saved = saveState(); renderContracts(); renderEditTimes(); closeContractModal(); showToast(saved ? (contractId ? 'Tile updated' : 'Tile added to dashboard') : 'Changes made, but could not be saved (storage limit reached — try a smaller image)'); }; const proceedWithSave = () => { if (imageFile && imageFile.size) { const reader = new FileReader(); reader.onload = () => finishSaveContract(reader.result); reader.readAsDataURL(imageFile); } else { finishSaveContract(null); } }; const isDuplicate = !contractId && state.contracts.some((item) => item.customerName === customerName && item.number === number && item.suffix === suffix); if (isDuplicate) { showConfirm('A tile for this customer, contract number and suffix already exists. Add it anyway?').then((confirmed) => { if (confirmed) proceedWithSave(); }); } else { proceedWithSave(); } }
