function saveDefaultWorkingTimeField(path, value) { if (path[0] === 'break') { state.defaultWorkingTimes.breaks[path[1]][path[2]] = value; } else { state.defaultWorkingTimes[path[0]] = value; } saveState(); }
function addUserFromList() { const id = `user-${Date.now()}`; state.users.push({ id, name: '', email: '', userType: 'user', costCentre: '' }); state.workingTimes.push({ id: `wt-${id}`, userId: id, start: state.defaultWorkingTimes.start, end: state.defaultWorkingTimes.end, breaks: state.defaultWorkingTimes.breaks.map((brk, index) => ({ id: `break-${id}-${index}`, type: 'Break', start: brk.start, end: brk.end })) }); saveState(); renderUserList(); renderWorkingTimes(); }
function renderContractInfo() { const rows = $('#contract-info-rows'); if (!rows) return; $('#contract-info-empty').classList.toggle('is-hidden', state.contractInfo.length > 0); rows.innerHTML = state.contractInfo.map(contractInfoRowTemplate).join(''); rows.querySelectorAll('[data-info-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.infoId); record[input.dataset.infoField] = input.value.trim(); saveState(); renderContractInfo(); })); rows.querySelectorAll('[data-suffix-field]').forEach((input) => input.addEventListener('change', () => { const record = state.contractInfo.find((item) => item.id === input.dataset.parentId); const suffix = record?.suffixes.find((item) => item.id === input.dataset.suffixId); if (!suffix) return; let value = input.value.trim(); if (input.dataset.suffixField === 'letter') value = value.toUpperCase(); suffix[input.dataset.suffixField] = value; saveState(); renderContractInfo(); })); rows.querySelectorAll('.expand-suffixes').forEach((button) => button.addEventListener('click', () => toggleContractInfoExpand(button.dataset.infoId))); rows.querySelectorAll('.add-suffix-row').forEach((button) => button.addEventListener('click', () => addSuffixRow(button.dataset.parentId))); rows.querySelectorAll('.remove-suffix-row').forEach((button) => button.addEventListener('click', () => { showConfirm('Remove this suffix?').then((confirmed) => { if (confirmed) removeSuffixRow(button.dataset.parentId, button.dataset.suffixId); }); })); rows.querySelectorAll('.delete-row:not(.remove-suffix-row)').forEach((button) => button.addEventListener('click', () => { showConfirm('Remove this contract information entry?').then((confirmed) => { if (confirmed) removeContractInfo(button.dataset.infoId); }); })); }
function contractInfoLinkCell(record, field) { return `<div class="link-cell"><input type="url" data-info-id="${record.id}" data-info-field="${field}" value="${record[field]}" placeholder="https://..."/>${record[field] ? `<a class="open-link" href="${record[field]}" target="_blank" rel="noopener noreferrer" title="Open link" aria-label="Open link">&#8599;</a>` : ''}</div>`; }
function contractInfoRowTemplate(record) { const parentRow = `<tr class="contract-info-row"><td><input type="text" data-info-id="${record.id}" data-info-field="number" value="${record.number}" placeholder="e.g. CNT-1048"></td><td><select data-info-id="${record.id}" data-info-field="machineType">${machineTypeOptionsHtml(record.machineType)}</select></td><td><select class="force-uppercase" data-info-id="${record.id}" data-info-field="customerName">${customerOptionsHtml(record.customerName)}</select></td><td>${contractInfoLinkCell(record, 'oneDriveLink')}</td><td>${contractInfoLinkCell(record, 'orderConfirmationLink')}</td><td><button class="expand-suffixes ${record.expanded ? 'is-expanded' : ''}" data-info-id="${record.id}" type="button" title="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}" aria-label="${record.expanded ? 'Hide suffixes' : 'Show suffixes'}"><span class="nav-chevron"></span></button></td><td><button class="delete-row" data-info-id="${record.id}" type="button" title="Remove entry" aria-label="Remove entry">&times;</button></td></tr>`; const childRow = `<tr class="suffix-row-container ${record.expanded ? '' : 'is-hidden'}"><td colspan="7">${suffixSubtableTemplate(record)}</td></tr>`; return parentRow + childRow; }
function suffixSubtableTemplate(record) { const suffixRows = record.suffixes.map((suffix) => suffixRowTemplate(record.id, suffix)).join('') || '<tr><td colspan="3" class="suffix-empty">No suffixes yet.</td></tr>'; return `<div class="suffix-subtable"><table><thead><tr><th class="col-narrow">Suffix letter</th><th class="col-suffix-desc">Description</th><th class="col-icon"></th></tr></thead><tbody>${suffixRows}</tbody></table><button class="add-button add-suffix-row" data-parent-id="${record.id}" type="button">+ Add suffix</button></div>`; }
function suffixDescriptionOptionsHtml(selected) { return '<option value="">Select suffix description</option>' + state.suffixDescriptions.map((desc) => `<option value="${desc}" ${desc === selected ? 'selected' : ''}>${desc}</option>`).join(''); }
function suffixRowTemplate(parentId, suffix) { return `<tr><td><input type="text" class="force-uppercase" data-parent-id="${parentId}" data-suffix-id="${suffix.id}" data-suffix-field="letter" value="${suffix.letter}" placeholder="e.g. A"></td><td><select data-parent-id="${parentId}" data-suffix-id="${suffix.id}" data-suffix-field="description">${suffixDescriptionOptionsHtml(suffix.description)}</select></td><td><button class="delete-row remove-suffix-row" data-parent-id="${parentId}" data-suffix-id="${suffix.id}" type="button" title="Remove suffix" aria-label="Remove suffix">&times;</button></td></tr>`; }
function toggleContractInfoExpand(id) { const record = state.contractInfo.find((item) => item.id === id); if (!record) return; record.expanded = !record.expanded; saveState(); renderContractInfo(); }
function addSuffixRow(parentId) { const record = state.contractInfo.find((item) => item.id === parentId); if (!record) return; record.suffixes.push({ id: `suffix-${Date.now()}`, letter: '', description: '' }); record.expanded = true; saveState(); renderContractInfo(); }
function removeSuffixRow(parentId, suffixId) { const record = state.contractInfo.find((item) => item.id === parentId); if (!record) return; record.suffixes = record.suffixes.filter((item) => item.id !== suffixId); saveState(); renderContractInfo(); }
function addContractInfo() { const id = `info-${Date.now()}`; state.contractInfo.push({ id, number: '', machineType: '', customerName: '', oneDriveLink: '', orderConfirmationLink: '', expanded: true, suffixes: [] }); saveState(); renderContractInfo(); }
function removeContractInfo(id) { state.contractInfo = state.contractInfo.filter((item) => item.id !== id); saveState(); renderContractInfo(); showToast('Contract information entry removed'); }
let confirmResolve = null;
function showConfirm(message, confirmLabel = 'Confirm') { return new Promise((resolve) => { confirmResolve = resolve; $('#confirm-modal-message').textContent = message; $('#confirm-modal-confirm').textContent = confirmLabel; $('#confirm-modal').classList.remove('is-hidden'); }); }
function closeConfirmModal(result) { $('#confirm-modal').classList.add('is-hidden'); if (confirmResolve) { confirmResolve(result); confirmResolve = null; } }
function showToast(message) { const toast = $('#toast'); toast.textContent = message; toast.classList.add('is-visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2300); }
function commitTimes() { const date = $('#edit-times-date').value; if (isDateCommitted(date)) { if (!state.adminMode) return; state.committedDates = state.committedDates.filter((item) => item !== date); saveState(); renderEditTimes(); showToast(`Commit removed for ${date}`); return; } state.committedDates.push(date); saveState(); renderEditTimes(); showToast(`Times committed for ${date}`); }
function updateCommittedUi() { const date = $('#edit-times-date').value; const committed = isDateCommitted(date); const locked = committed && !state.adminMode; $('#admin-mode-toggle').checked = state.adminMode; $('#committed-badge').classList.toggle('is-hidden', !committed); $('#edit-times-card').classList.toggle('is-locked', locked); const commitButton = $('#commit-times'); if (committed && state.adminMode) { commitButton.textContent = 'Uncommit'; commitButton.disabled = false; } else if (committed) { commitButton.textContent = 'Committed'; commitButton.disabled = true; } else { commitButton.textContent = 'Commit'; commitButton.disabled = false; } }
function pauseRunningContract(contract) { if (!contract?.startedAt) return; recordSession(contract, contract.startedAt, Date.now()); contract.startedAt = null; }
function handleBreakState() { const breakItem = currentBreak(); if (breakItem && !state.breakState) { const runningContract = state.contracts.find((contract) => contract.startedAt); if (runningContract) { pauseRunningContract(runningContract); state.breakState = { contractId: runningContract.id }; saveState(); showToast(`${runningContract.customerName} paused for break`); } } else if (!breakItem && state.breakState) { const pausedContract = state.contracts.find((contract) => contract.id === state.breakState.contractId); if (pausedContract && !state.contracts.some((contract) => contract.startedAt)) { pausedContract.startedAt = Date.now(); showToast(`${pausedContract.customerName} resumed after break`); } state.breakState = null; saveState(); } }
function tick() { handleBreakState(); state.contracts.filter((contract) => contract.startedAt).forEach((contract) => { const live = document.querySelector(`[data-live-id="${contract.id}"]`); if (live) live.textContent = formatTime(Math.floor((Date.now() - contract.startedAt) / 1000)); }); updateMetrics(); }
document.querySelectorAll('.nav-item[data-view]').forEach((button) => button.addEventListener('click', () => { document.querySelectorAll('.nav-item[data-view]').forEach((item) => item.classList.toggle('is-active', item === button)); document.querySelectorAll('[data-view-panel]').forEach((panel) => panel.classList.toggle('is-hidden', panel.dataset.viewPanel !== button.dataset.view)); }));
